<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ProvincialLeader extends Model { protected $guarded=[]; protected function casts():array{return ['is_active'=>'boolean'];} public function getPhotoUrlAttribute(): string { return str_starts_with((string) $this->photo_path, 'assets/') || str_starts_with((string) $this->photo_path, 'storage/') ? asset($this->photo_path) : asset('storage/'.$this->photo_path); } }
